// Pinehurst's official scorecard: U.S. Open, Blue and White tees.
// Screen geometry is illustrative; it is not measured against the drone footage.
export const teeSets={
 open:{name:'U.S. Open',yards:[402,507,387,529,576,242,424,502,191,617,483,484,385,473,202,528,205,451],pars:[4,4,4,4,5,3,4,4,3,5,4,4,4,4,3,4,3,4]},
 blue:{name:'Blue',yards:[393,439,350,474,508,203,393,469,174,580,455,419,375,433,183,513,185,415],pars:[4,4,4,4,5,3,4,5,3,5,4,4,4,4,3,5,3,4]},
 white:{name:'White',yards:[376,411,330,434,462,178,385,440,148,455,375,360,358,419,170,478,162,366],pars:[4,4,4,4,5,3,4,5,3,5,4,4,4,4,3,5,3,4]}
};
export function shotPlan(hole,tee='open',carry=250){const set=teeSets[tee]||teeSets.open;if(!Number.isInteger(hole)||hole<1||hole>18)throw new RangeError('Hole must be 1–18');const length=set.yards[hole-1];const requested=Math.max(50,Math.min(350,Number(carry)||250));const landing=Math.min(length,requested);return {yards:length,par:set.pars[hole-1],carry:landing,remaining:length-landing,teeName:set.name,ticks:Array.from({length:Math.floor((length-1)/50)},(_,i)=>(i+1)*50)};}
export function arcPoint(t,start,end,height=20){const k=Math.max(0,Math.min(1,t));return {x:start.x+(end.x-start.x)*k,y:start.y+(end.y-start.y)*k-4*k*(1-k)*height};}
export function shotScene(plan,camera=0){const p=Math.max(0,Math.min(1,camera));const origin={x:49-p*4,y:76+p*15},green={x:56-p*5,y:32+p*17};const ratio=plan.carry/plan.yards;const landing={x:origin.x+(green.x-origin.x)*ratio,y:origin.y+(green.y-origin.y)*ratio};return {origin,landing,green};}
export function shotControls(){return `<aside class="shot-controls"><div class="shot-yardage"><span id="shot-tee-caption">U.S. OPEN TEES</span><strong><span id="shot-hole-yards">402</span><small> YDS</small></strong><span id="shot-par-caption">PAR 4</span></div><details id="shot-settings"><summary>Yardage & ball flight <span>⌄</span></summary><div class="shot-settings-content"><label for="shot-tee">Tee set</label><select id="shot-tee"><option value="open">U.S. Open</option><option value="blue">Blue</option><option value="white">White</option></select><label for="shot-carry">Illustrative carry</label><select id="shot-carry"><option value="150">150 yards</option><option value="200">200 yards</option><option value="250" selected>250 yards</option><option value="300">300 yards</option></select><label class="shot-check"><input type="checkbox" id="shot-show-yards" checked> Yardage markers</label><label class="shot-check"><input type="checkbox" id="shot-show-flight" checked> Ball-flight line</label><button id="shot-replay" class="secondary">Replay shot ↗</button><p>Illustrative shot, not a measured shot recommendation or GPS yardage.</p></div></details><div class="shot-summary"><span><b id="shot-carry-readout">250</b> yd carry</span><span><b id="shot-remaining">152</b> yd left</span></div><small>DEMO FLIGHT · NOT MEASURED</small></aside>`;}
export function shotOverlay(){return `<svg class="shot-overlay" viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="Illustrative ball flight and distance markers"><defs><filter id="shot-glow"><feGaussianBlur stdDeviation=".12"/></filter></defs><g id="shot-yardage-markers"></g><g id="shot-trace"><path id="shot-ground" fill="none" stroke="#d9e5bf" stroke-width=".1" stroke-dasharray=".4 .6" opacity=".5"/><path id="shot-arc-shadow" fill="none" stroke="#0b281e" stroke-width=".7" opacity=".3"/><path id="shot-arc" fill="none" stroke="#f2e5a9" stroke-width=".2"/><ellipse id="shot-landing" rx="2.3" ry=".6" fill="#eedaa526" stroke="#f2e5a9" stroke-width=".12"/><circle id="shot-ball" r=".45" fill="#fffef1" stroke="#274b34" stroke-width=".1"/></g></svg>`;}
export function mountShots(root,requestUpdate,reduced){let tee='open',carry=250,showYards=true,showFlight=true,replayStart=null,replayFrame=0,lastHole=1,lastCamera=0;const controls=root.querySelector('.shot-controls');
 function draw(hole,camera){if(hole!==lastHole)replayStart=null;lastHole=hole;lastCamera=camera;const plan=shotPlan(hole,tee,carry),scene=shotScene(plan,camera),{origin,landing,green}=scene;
 root.querySelector('#shot-hole-yards').textContent=plan.yards;root.querySelector('#shot-tee-caption').textContent=`${plan.teeName.toUpperCase()} TEES`;root.querySelector('#shot-par-caption').textContent=`PAR ${plan.par}`;root.querySelector('#shot-carry-readout').textContent=plan.carry;root.querySelector('#shot-remaining').textContent=plan.remaining;
 root.querySelector(`[data-flight-panel="${hole}"] .flight-label`).textContent=`${hole<10?'THE FRONT NINE':'THE BACK NINE'} · PAR ${plan.par} · ${plan.yards} YDS · ${plan.teeName.toUpperCase()}`;
 const markers=root.querySelector('#shot-yardage-markers');markers.hidden=!showYards;markers.style.display=showYards?'':'none';markers.innerHTML=showYards?plan.ticks.map(y=>{const f=y/plan.yards;const x=origin.x+(green.x-origin.x)*f,pos=origin.y+(green.y-origin.y)*f,width=7-4*f;return `<g><path d="M${x-width} ${pos}Q${x} ${pos+1.2} ${x+width} ${pos}" fill="none" stroke="#e4edcf" stroke-width=".12" opacity=".7"/><text x="${x+width+1}" y="${pos+.3}" fill="#f2f5e3" stroke="#183b2c" stroke-width=".05" paint-order="stroke" font-size="1" font-family="sans-serif">${y} yd</text></g>`;}).join(''):'';
 const trace=root.querySelector('#shot-trace');trace.style.display=showFlight?'':'none';const mid={x:(origin.x+landing.x)/2,y:(origin.y+landing.y)/2-25};const path=`M${origin.x} ${origin.y} Q${mid.x} ${mid.y} ${landing.x} ${landing.y}`;
 for(const id of ['shot-arc','shot-arc-shadow'])root.querySelector('#'+id).setAttribute('d',path);root.querySelector('#shot-ground').setAttribute('d',`M${origin.x} ${origin.y}L${green.x} ${green.y}`);const ring=root.querySelector('#shot-landing');ring.setAttribute('cx',landing.x);ring.setAttribute('cy',landing.y);
 const replay=replayStart!==null?Math.min(1,(performance.now()-replayStart)/1700):null;const t=reduced.matches?1:replay??Math.max(0,Math.min(1,camera));const ball=arcPoint(t,origin,landing,12.5);const dot=root.querySelector('#shot-ball');dot.setAttribute('cx',ball.x);dot.setAttribute('cy',ball.y);root.querySelector('#shot-arc').style.strokeDasharray='none';
 if(replay!==null&&replay<1&&!replayFrame)replayFrame=requestAnimationFrame(()=>{replayFrame=0;draw(lastHole,lastCamera);});if(replay===1)replayStart=null;
 }
 function change(e){if(e.target.id==='shot-tee')tee=e.target.value;if(e.target.id==='shot-carry')carry=+e.target.value;if(e.target.id==='shot-show-yards')showYards=e.target.checked;if(e.target.id==='shot-show-flight')showFlight=e.target.checked;draw(lastHole,lastCamera);requestUpdate();}
 function click(e){if(e.target.closest('#shot-replay')){showFlight=true;root.querySelector('#shot-show-flight').checked=true;replayStart=reduced.matches?null:performance.now();draw(lastHole,lastCamera);}}
 controls.addEventListener('change',change);controls.addEventListener('click',click);return {draw,destroy(){cancelAnimationFrame(replayFrame);controls.removeEventListener('change',change);controls.removeEventListener('click',click);}};
}
